package io.github.windyzhu3.ontologylaw.transfer;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class TransferSubmissionInputTest {
 private TransferSubmissionInput.Material material(){return new TransferSubmissionInput.Material(UUID.randomUUID(),"ab".repeat(32));}
 @Test void submission_requires_exact_materials_and_manual_consistency_confirmation(){var identity=material();var archive=material();assertThrows(IllegalArgumentException.class,()->new TransferSubmissionInput(identity,archive,"Handover",false,List.of()));assertThrows(IllegalArgumentException.class,()->new TransferSubmissionInput(identity,null,"Handover",true,List.of()));assertThrows(IllegalArgumentException.class,()->new TransferSubmissionInput(identity,archive," ",true,List.of()));assertDoesNotThrow(()->new TransferSubmissionInput(identity,archive,"Handover",true,List.of()));}
 @Test void correction_must_respond_to_every_exact_return_item_without_extra_or_duplicate_answers(){UUID one=UUID.randomUUID(),two=UUID.randomUUID();var a=new TransferSubmissionInput.Correction(one,"Identity proof replaced");var b=new TransferSubmissionInput.Correction(two,"Signature archive replaced");var value=new TransferSubmissionInput(material(),material(),"Corrected handover",true,List.of(a,b));assertDoesNotThrow(()->value.requireReturnItems(Set.of(one,two)));assertThrows(IllegalArgumentException.class,()->value.requireReturnItems(Set.of(one)));assertThrows(IllegalArgumentException.class,()->new TransferSubmissionInput(material(),material(),"Corrected",true,List.of(a,a)));assertThrows(IllegalArgumentException.class,()->new TransferSubmissionInput(material(),material(),"Corrected",true,List.of(a)).requireReturnItems(Set.of(one,two)));}
 @Test void protected_handover_text_is_not_in_default_logs(){var value=new TransferSubmissionInput(material(),material(),"PRIVATE-CLIENT-DETAIL",true,List.of());assertFalse(value.toString().contains("PRIVATE-CLIENT-DETAIL"));}
}
